import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';

const Services = () => {
    const [menuOpen, setMenuOpen] = useState(false);
    const [services, setServices] = useState([]);
    const [loadingServices, setLoadingServices] = useState(true);
    const [loadingId, setLoadingId] = useState(null);
    const navigate = useNavigate();
    const location = useLocation();

    // 1. Fetch REAL services from the database
    useEffect(() => {
        const fetchServices = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/services', {
                    headers: { Authorization: `Bearer ${token}` }
                });
                setServices(res.data.data);
            } catch (err) {
                console.error("Failed to fetch services", err);
                setServices([]);
            } finally {
                setLoadingServices(false);
            }
        };
        fetchServices();
    }, []);

    // 2. Fetch appointments to calculate discounts
    const [discountedServices, setDiscountedServices] = useState({});
    useEffect(() => {
        const checkDiscounts = async () => {
            try {
                const token = localStorage.getItem('token');
                const res = await axios.get('http://localhost:5000/api/appointments', {
                    headers: { Authorization: `Bearer ${token}` }
                });

                // Count confirmed appointments per service
                const counts = {};
                res.data.data.forEach(app => {
                    const serviceId = app.service?._id;
                    if (serviceId && app.status === 'Confirmed') {
                        counts[serviceId] = (counts[serviceId] || 0) + 1;
                    }
                });

                // Mark services with >= 5 confirmed appointments
                const discountMap = {};
                Object.entries(counts).forEach(([serviceId, count]) => {
                    if (count >= 5) {
                        discountMap[serviceId] = true;
                    }
                });
                setDiscountedServices(discountMap);
            } catch (err) {
                console.error("Failed to check discounts", err);
            }
        };
        checkDiscounts();
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        navigate('/login');
    };

    const toggleMenu = () => setMenuOpen(!menuOpen);
    const isActive = (path) => location.pathname === path;

    const handleBookAppointment = async (service) => {
        setLoadingId(service._id);
        try {
            const token = localStorage.getItem('token');
            const today = new Date().toISOString().split('T')[0];
            const startTime = "10:00";
            const endTime = "11:00";

            await axios.post('http://localhost:5000/api/appointments', {
                serviceId: service._id,
                appointmentDate: today,
                startTime: startTime,
                endTime: endTime,
                notes: ""
            }, {
                headers: { Authorization: `Bearer ${token}` }
            });

            alert(`✅ ${service.name} booked successfully!`);
        } catch (error) {
            console.error("Booking Error:", error.response?.data || error.message);
            alert('❌ Failed to book appointment. Please try again.');
        } finally {
            setLoadingId(null);
        }
    };

    return (
        <div className="services-page">
            <nav className="services-navbar">
                <div className="nav-logo">BeautyBook</div>
                <div className="hamburger" onClick={toggleMenu}>☰</div>
                <div className="nav-links desktop-nav">
                    <span className={`nav-item ${isActive('/services') ? 'active' : ''}`}>🌸 Beauty treatments</span>
                    <span className={`nav-item ${isActive('/appointments') ? 'active' : ''}`} onClick={() => navigate('/appointments')}>📅 Appointment</span>
                    <span className="nav-icon">🔔</span>
                    <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                </div>
            </nav>

            <div className={`mobile-menu ${menuOpen ? 'open' : ''}`}>
                <div className="mobile-menu-content">
                    <span className={`mobile-nav-item ${isActive('/services') ? 'active' : ''}`}>🌸 Beauty treatments</span>
                    <span className={`mobile-nav-item ${isActive('/appointments') ? 'active' : ''}`} onClick={() => { setMenuOpen(false); navigate('/appointments'); }}>📅 Appointment</span>
                    <div className="mobile-nav-icons">
                        <span className="nav-icon">🔔</span>
                        <span className="nav-icon" onClick={handleLogout} style={{cursor: 'pointer'}}>⚙️</span>
                    </div>
                </div>
            </div>

            <div className="services-grid-container">
                <div className="services-grid">
                    {loadingServices ? (
                        <div className="loading">Loading services...</div>
                    ) : services.length === 0 ? (
                        <div className="empty-services">No services available.</div>
                    ) : (
                        services.map((service) => (
                            <div key={service._id} className="service-card">
                                {/* Show 15% tag if eligible */}
                                {discountedServices[service._id] && (
                                    <div className="discount-tag">15%</div>
                                )}

                                <div className="service-image-wrapper">
                                    <img src={service.image} alt={service.name} className="service-image" />
                                </div>
                                <h3 className="service-title">{service.name}</h3>
                                <div className="service-details">
                                    <span>Durée: {service.duration} min</span>
                                    <span>Prix: {service.price} DA</span>
                                </div>
                                <button 
                                    className="service-btn" 
                                    onClick={() => handleBookAppointment(service)}
                                    disabled={loadingId === service._id}
                                >
                                    {loadingId === service._id ? 'Booking...' : 'Add to appointment'}
                                </button>
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
};

export default Services;
